import {
  cardOverlayTargets,
  cardOverlaysAllowed,
  contextKey,
  FUSION_REVIEW_GRID,
  inFusionReview,
  isFusionPage,
  resolveCard,
  topDialog,
  MARKET_ACTIVITY_LINK,
  MARKET_ACTIVITY_ROW,
} from "../kosmora/dom";
import type { CardContext, Settings } from "../shared/types";
import { settingsForPage } from "../shared/page-settings";
import { affected, observePage, type PageChanges } from "./page-changes";
import { el } from "./ui";
import logo from "./kosmora-logo.svg?raw";

interface Entry {
  root: HTMLElement;
  context: CardContext;
  key: string;
  host: HTMLElement;
  mount: HTMLElement;
  button: HTMLButtonElement;
  summaryResize?: ResizeObserver;
}
interface Mount {
  count: number;
  isolation?: string;
  position?: { value: string; priority: string };
}
const LOGO = `data:image/svg+xml,${encodeURIComponent(logo)}`;
const STYLE = `
:host{all:initial;position:absolute;display:block;width:44px;height:44px;left:-14px;bottom:-14px;z-index:20;pointer-events:none}
:host([data-inset]){left:0;bottom:0}
button{all:initial;box-sizing:border-box;display:grid;place-items:center;width:44px;height:44px;padding:4px;border-radius:50%;pointer-events:auto;cursor:pointer;touch-action:manipulation;-webkit-tap-highlight-color:transparent}
button[hidden]{display:none}
img{display:block;box-sizing:border-box;width:36px;height:36px;background:#171027;border-radius:50%;box-shadow:0 2px 6px #0009;pointer-events:none}
button:hover img{filter:brightness(1.15)}
button:focus-visible{outline:2px solid #f3dda8;outline-offset:1px}
`;

/** Local absolute anchors scroll with their cards, without scroll-event positioning. */
export class TooltipButtons {
  private entries = new Map<HTMLElement, Entry>();
  private mounts = new Map<HTMLElement, Mount>();
  private settings?: Settings;
  constructor(private open: (context: CardContext) => void) {}
  start() {
    observePage((changes) => this.scan(changes));
    window.addEventListener("resize", () => this.scan());
    window.addEventListener("popstate", () => this.scan());
  }
  setSettings(settings: Settings) {
    this.settings = settings;
    this.scan();
  }
  contains(target: Element) {
    return !!target.closest("[data-kosmore-tooltip-buttons]");
  }
  focus(context: CardContext) {
    const entry = this.entryFor(context);
    if (entry && !entry.button.hidden)
      entry.button.focus({ preventScroll: true });
  }
  showing(context: CardContext) {
    const entry = this.entryFor(context);
    return !!entry?.host.isConnected && !entry.button.hidden;
  }
  private entryFor(context: CardContext) {
    return [...this.entries.values()].find(
      (entry) =>
        entry.context.anchor === context.anchor &&
        entry.key === contextKey(context),
    );
  }
  usesButton(anchor: Element, settings = this.settings) {
    return (
      !!settings &&
      (settings.useOverlayButtonInsteadOfHover ||
        (settings.fusionSettingsEnabled &&
          settings.fusionReviewOverlayButton &&
          inFusionReview(anchor)))
    );
  }
  private enabled() {
    return (
      this.settings &&
      settingsForPage(this.settings, location.pathname).enabled &&
      (this.settings.useOverlayButtonInsteadOfHover ||
        (this.settings.fusionSettingsEnabled &&
          this.settings.fusionReviewOverlayButton &&
          isFusionPage()))
    );
  }
  private contextOf(root: HTMLElement) {
    if (location.pathname === "/market" && root.matches(MARKET_ACTIVITY_ROW)) {
      const link = root.querySelector<HTMLAnchorElement>(MARKET_ACTIVITY_LINK);
      return link ? resolveCard(link) : null;
    }
    if (root.matches(".bsell-row")) {
      const head = root.querySelector<HTMLElement>(".bsell-head");
      return location.pathname === "/market/sell/batch" && head
        ? resolveCard(head)
        : null;
    }
    return cardOverlaysAllowed(root) ? resolveCard(root) : null;
  }
  private targets(scope: Document | Element) {
    const targets = cardOverlayTargets(document, scope);
    if (location.pathname === "/market") {
      const enclosing =
        scope instanceof Element
          ? scope.closest<HTMLElement>(MARKET_ACTIVITY_ROW)
          : null;
      for (const row of [
        ...(enclosing ? [enclosing] : []),
        ...scope.querySelectorAll<HTMLElement>(MARKET_ACTIVITY_ROW),
      ]) {
        const context = this.contextOf(row);
        if (context) targets.set(row, context);
      }
    }
    if (location.pathname === "/market/sell/batch") {
      const enclosing =
        scope instanceof Element
          ? scope.closest<HTMLElement>(".bsell-row")
          : null;
      for (const row of [
        ...(enclosing ? [enclosing] : []),
        ...scope.querySelectorAll<HTMLElement>(".bsell-row"),
      ]) {
        const context = this.contextOf(row);
        if (context) targets.set(row, context);
      }
    }
    return targets;
  }
  private scan(changes?: PageChanges) {
    if (!this.enabled()) {
      for (const entry of this.entries.values()) this.remove(entry);
      this.entries.clear();
      return;
    }
    for (const [root, entry] of this.entries) {
      if (
        changes &&
        !affected(entry.summaryResize ? entry.mount : root, changes)
      )
        continue;
      const context =
        root.isConnected && this.usesButton(root) ? this.contextOf(root) : null;
      if (
        !context ||
        contextKey(context) !== entry.key ||
        this.mountFor(root) !== entry.mount
      ) {
        this.remove(entry);
        this.entries.delete(root);
      } else {
        entry.context = context;
        if (!entry.host.isConnected) entry.mount.append(entry.host);
        if (entry.summaryResize) this.positionSummaryButton(entry);
      }
    }
    const scopes = !changes || changes.full ? [document] : changes.roots;
    for (const scope of scopes) {
      // With only the Fusion preference enabled, scan cards in the review grid.
      const targetScope =
        this.settings!.useOverlayButtonInsteadOfHover ||
        (scope instanceof Element && scope.closest(FUSION_REVIEW_GRID))
          ? scope
          : scope.querySelector(FUSION_REVIEW_GRID);
      if (!targetScope) continue;
      for (const [root, context] of this.targets(targetScope)) {
        if (this.entries.has(root)) continue;
        const host = el("span"),
          button = el("button"),
          img = el("img"),
          style = el("style");
        host.setAttribute("data-kosmore-tooltip-buttons", "");
        style.textContent = STYLE;
        button.type = "button";
        button.setAttribute(
          "aria-label",
          `Open card tooltip for ${context.name}`,
        );
        button.setAttribute("aria-haspopup", "dialog");
        img.src = LOGO;
        img.alt = "";
        button.append(img);
        host.attachShadow({ mode: "open" }).append(style, button);
        const mount = this.mountFor(root);
        if (!mount) continue;
        this.retainMount(mount);
        const mountStyle = getComputedStyle(mount);
        if (/(hidden|clip|scroll|auto)/.test(mountStyle.overflow))
          host.setAttribute("data-inset", "");
        else {
          host.style.left = -14 - parseFloat(mountStyle.borderLeftWidth) + "px";
          host.style.bottom =
            -14 - parseFloat(mountStyle.borderBottomWidth) + "px";
        }
        const entry: Entry = {
          root,
          context,
          key: contextKey(context),
          host,
          mount,
          button,
        };
        for (const type of [
          "pointerdown",
          "pointerup",
          "mousedown",
          "mouseup",
          "dblclick",
          "auxclick",
        ])
          button.addEventListener(type, (event) => event.stopPropagation());
        for (const type of ["keydown", "keyup"])
          button.addEventListener(type, (event) => {
            if (["Enter", " "].includes((event as KeyboardEvent).key))
              event.stopPropagation();
          });
        button.addEventListener("click", (event) => {
          event.preventDefault();
          event.stopPropagation();
          const next = this.contextOf(root);
          if (
            this.enabled() &&
            this.usesButton(root) &&
            next &&
            contextKey(next) === entry.key &&
            !button.hidden
          )
            this.open(next);
        });
        this.entries.set(root, entry);
        mount.append(host);
        if (context.surface === "summary" && mount !== root) {
          this.positionSummaryButton(entry);
          entry.summaryResize = new ResizeObserver(() => this.positionSummaryButton(entry));
          entry.summaryResize.observe(root, { box: "border-box" });
          entry.summaryResize.observe(mount, { box: "border-box" });
        }
      }
    }
    const dialog = topDialog();
    for (const entry of this.entries.values()) {
      entry.button.hidden = !!dialog && !dialog.contains(entry.root);
    }
  }
  private mountFor(root: HTMLElement): HTMLElement | null {
    // Card-wide picker hit targets are siblings of the face. Anchor to their
    // shared tile so both controls participate in the same local stacking context.
    return (
      root.closest<HTMLElement>(".pick, .ko-summary .ko-grid > li") ?? root
    );
  }
  private positionSummaryButton({ root, mount, host }: Entry) {
    // Keep the button above the native tile hit target, but measure from the
    // card face. Captions and grid row stretching can extend the tile below it.
    let left = root.offsetLeft;
    let top = root.offsetTop;
    for (let parent = root.offsetParent; parent !== mount; parent = parent.offsetParent) {
      if (!(parent instanceof HTMLElement)) return;
      left += parent.offsetLeft + parent.clientLeft;
      top += parent.offsetTop + parent.clientTop;
    }
    const bottom = mount.clientHeight - top - root.offsetHeight;
    const inset = host.hasAttribute("data-inset");
    host.style.left = (inset ? Math.max(0, left - 14) : left - 14) + "px";
    host.style.bottom = (inset ? Math.max(0, bottom - 14) : bottom - 14) + "px";
  }
  private retainMount(mount: HTMLElement) {
    let state = this.mounts.get(mount);
    if (state) {
      state.count++;
      return;
    }
    state = { count: 1 };
    if (getComputedStyle(mount).position === "static") {
      state.position = {
        value: mount.style.getPropertyValue("position"),
        priority: mount.style.getPropertyPriority("position"),
      };
      mount.style.setProperty("position", "relative");
    }
    this.mounts.set(mount, state);
    if (getComputedStyle(mount).isolation !== "isolate") {
      state.isolation = mount.style.isolation;
      mount.style.isolation = "isolate";
    }
  }
  private remove(entry: Entry) {
    entry.summaryResize?.disconnect();
    entry.host.remove();
    const state = this.mounts.get(entry.mount)!;
    if (--state.count) return;
    this.mounts.delete(entry.mount);
    if (
      state.isolation !== undefined &&
      entry.mount.style.isolation === "isolate"
    )
      entry.mount.style.isolation = state.isolation;
    // Existing card overlays may have adopted this same positioning anchor.
    if (
      state.position &&
      entry.mount.style.getPropertyValue("position") === "relative" &&
      !entry.mount.style.getPropertyPriority("position") &&
      !entry.mount.querySelector(
        ":scope > [data-kosmore-card-overlays],:scope > [data-kosmore-fusion-family]",
      )
    ) {
      if (state.position.value)
        entry.mount.style.setProperty(
          "position",
          state.position.value,
          state.position.priority,
        );
      else entry.mount.style.removeProperty("position");
    }
  }
}
